'use strict';

// MODULES //

var storeMatrix = require( './store_matrix.js' );


// FUNCTIONS //

/**
* Returns layout options.
*
* @private
* @param {string} order - storage layout
* @param {boolean} flip - boolean indicating whether to negate the stride of the first dimension
* @returns {Object} options
*/
function layout( order, flip ) {
	return {
		'order': order,
		'pad': 1,
		'offset': 2,
		'tail': 1,
		'flip1': flip,
		'flip2': false
	};
}


// MAIN //

/**
* Returns a problem `C = α*op(A)*op(B) + β*C` whose matrices are stored from dense matrices using a specified configuration.
*
* ## Notes
*
* -   Each matrix is stored using a leading-dimension padding of one element, two leading elements, and one trailing element.
*
* @private
* @param {Collection} X - dense `M×K` matrix (row-major) such that `op(A) = X`
* @param {Collection} Y - dense `K×N` matrix (row-major) such that `op(B) = Y`
* @param {Collection} Z - dense `M×N` matrix (row-major) stored in `C`
* @param {NonNegativeIntegerArray} dims - dimensions `[ M, N, K ]`
* @param {Object} cfg - configuration
* @param {string} cfg.transA - transpose operation for `A`
* @param {string} cfg.transB - transpose operation for `B`
* @param {StringArray} cfg.orders - storage layouts of `A`, `B`, and `C`
* @param {boolean} cfg.flip - boolean indicating whether to negate the stride of the first dimension of each matrix
* @param {NumericArray} scalars - `[ α, β, cutoff, levels ]`
* @param {number} fill - value of buffer elements which do not belong to the matrices
* @returns {Object} problem
*/
function denseProblem( X, Y, Z, dims, cfg, scalars, fill ) {
	return {
		'transA': cfg.transA,
		'transB': cfg.transB,
		'M': dims[ 0 ],
		'N': dims[ 1 ],
		'K': dims[ 2 ],
		'alpha': scalars[ 0 ],
		'beta': scalars[ 1 ],
		'cutoff': scalars[ 2 ],
		'levels': scalars[ 3 ],
		'A': storeMatrix( X, dims[ 0 ], dims[ 2 ], cfg.transA, layout( cfg.orders[ 0 ], cfg.flip ), fill ),
		'B': storeMatrix( Y, dims[ 2 ], dims[ 1 ], cfg.transB, layout( cfg.orders[ 1 ], cfg.flip ), fill ),
		'C': storeMatrix( Z, dims[ 0 ], dims[ 1 ], 'no-transpose', layout( cfg.orders[ 2 ], cfg.flip ), fill )
	};
}


// EXPORTS //

module.exports = denseProblem;
